<div class="page-heading"><div><p class="eyebrow">Alunos</p><h1>Nova matrícula</h1><p class="meta">Escolha o curso, a condição comercial e o aluno.</p></div><a class="button-secondary" href="<?= $escape($basePath) ?>/students/enrollments">Cancelar</a></div><?php if($error):?><p class="alert alert-danger"><?= $escape($error) ?></p><?php endif;?><section class="card"><div class="card-body"><form method="post" action="<?= $escape($basePath) ?>/students/enrollments"><?= $csrfField ?><div class="form-grid"><div class="form-field"><label>1. Curso no Moodle <span class="required">*</span></label><select name="moodle_course_id" required><option value="">Selecione o curso</option><?php foreach($courses as$course):?><option value="<?= (int)$course['id'] ?>"><?= $escape($course['fullname'].' · '.$course['shortname']) ?></option><?php endforeach;?></select></div><div class="form-field"><label>2. Curso e preço da cobrança <span class="required">*</span></label><select name="finance_product_id" required><option value="">Selecione o preço</option><?php foreach($products as$product):?><option value="<?= (int)$product['id'] ?>"><?= $escape($product['name'].' · R$ '.number_format((float)$product['value'],2,',','.')) ?></option><?php endforeach;?></select></div><div class="form-field"><label>3. Campanha de desconto</label><select name="campaign_id"><option value="">Sem desconto</option><?php foreach($campaigns as$campaign):?><option value="<?= (int)$campaign['id'] ?>"><?= $escape($campaign['name'].' · '.number_format((float)$campaign['discount_percent'],2,',','.').'% · até '.date('d/m/Y',strtotime((string)$campaign['valid_until']))) ?></option><?php endforeach;?></select><small>Opcional. O desconto será fixado nesta matrícula.</small></div><div class="form-field"><label>4. Unidade <span class="required">*</span></label><select name="unit_id" required><option value="">Selecione</option><?php foreach($units as$unit):?><option value="<?= (int)$unit['id'] ?>"><?= $escape($unit['name']) ?></option><?php endforeach;?></select></div><div class="form-field"><label>5. Aluno <span class="required">*</span></label><select name="finance_customer_id" required><option value="">Selecione</option><?php foreach($students as$student):?><option value="<?= (int)$student['id'] ?>"><?= $escape($student['name'].' · '.$student['unit_name']) ?></option><?php endforeach;?></select></div></div><div class="alert alert-warning"><strong>Próxima etapa:</strong> o valor já sairá com o desconto da campanha selecionada.</div><button class="button-primary" type="submit"><i class="fa-solid fa-arrow-right"></i> Continuar para cobrança</button></form></div></section>
